const token = $('Confere token').first().json;
const itens = $input.all().map((i) => i.json);

// Airtable fora do ar: não é problema de acesso -- não pode derrubar a sessão.
if (itens.some((j) => j && j.error)) {
  return [{ json: { ok: false, mensagem: 'Não foi possível carregar agora. Tente de novo em instantes.' } }];
}
if (!token.valido) {
  return [{ json: { ok: false, acessoNegado: true, mensagem: 'Sua sessão expirou. Entre de novo.' } }];
}

// A busca volta com um item vazio ({}) quando a tabela não tem nada --
// só conta como registro o que tiver id de verdade.
const registros = itens.filter((r) => r && r.id);

// Papel e situação lidos agora do Airtable, não do token: um token emitido
// antes de a pessoa perder o acesso total ainda vale por até 30 minutos.
const chamador = registros.find((r) => r.id === token.usuarioId);
const c = (chamador && chamador.fields) || {};
if (!chamador || c.Ativo !== true || c.Papel !== 'Dono' || !c.Senha_Hash) {
  return [{ json: { ok: false, acessoNegado: true, mensagem: 'Só quem tem acesso total pode ver os usuários.' } }];
}

// Só o que a tela mostra. Hash de senha e código de verificação nunca saem daqui.
const ORDEM = { ativa: 0, pendente: 1, desativada: 2 };
const usuarios = registros
  .map((r) => {
    const f = r.fields || {};
    const situacao = !f.Senha_Hash ? 'pendente' : f.Ativo === true ? 'ativa' : 'desativada';
    return {
      id: r.id,
      nome: String(f.Nome || ''),
      email: String(f.Email || ''),
      papel: f.Papel === 'Dono' ? 'Dono' : 'Usuario',
      situacao,
      historico: String(f.Historico || ''),
      voce: r.id === chamador.id,
    };
  })
  .sort((a, b) => (ORDEM[a.situacao] - ORDEM[b.situacao])
    || (a.voce === b.voce ? 0 : a.voce ? -1 : 1)
    || (a.nome || a.email).localeCompare(b.nome || b.email, 'pt-BR'));

return [{ json: { ok: true, usuarios } }];
